<div class="page-heading"><div><h2><i class="bi bi-qr-code"></i> Etiqueta QR</h2><p>Imprime o descarga esta etiqueta para colocarla en el instrumento.</p></div><a class="btn btn-outline-primary" href="instrumentos.php"><i class="bi bi-arrow-left"></i> Instrumentos</a></div><section class="card scanner-card"><div class="card-header"><h3><i class="bi bi-qr-code"></i> <?=e($instrumento['tipo'])?></h3></div><div class="card-body text-center"><div id="qrcode" data-contenido="<?=e($url)?>" class="d-inline-block p-3 bg-white border rounded"></div><h4 class="mt-3 mb-1"><?=e($instrumento['codigo_qr'])?></h4><p class="text-muted"><?=e($instrumento['cliente_nombre'])?></p><div class="btn-toolbar justify-content-center"><button class="btn btn-primary" type="button" onclick="window.print()"><i class="bi bi-printer"></i> Imprimir etiqueta</button><button class="btn btn-success" type="button" id="descargar-qr"><i class="bi bi-download"></i> Descargar QR</button></div></div></section><script src="<?=e(BASE_URL)?>/assets/vendor/qrcode.min.js"></script><script>const contenedor=document.getElementById('qrcode');new QRCode(contenedor,{text:contenedor.dataset.contenido,width:220,height:220});document.getElementById('descargar-qr').addEventListener('click',()=>{const imagen=contenedor.querySelector('img')||contenedor.querySelector('canvas');if(!imagen)return;const enlace=document.createElement('a');enlace.download='<?=e($instrumento['codigo_qr'])?>.png';enlace.href=imagen.tagName.toLowerCase()==='canvas'?imagen.toDataURL('image/png'):imagen.src;enlace.click();});</script><?php require __DIR__.'/../../includes/footer.php';
